-- FIO Etapa 2: owner onboarding and client-facing identity. Additive only.
alter table public.barbershops add column if not exists onboarding_step integer not null default 1 check(onboarding_step between 1 and 5), add column if not exists onboarding_completed boolean not null default false, add column if not exists whatsapp text, add column if not exists instagram text, add column if not exists address text, add column if not exists theme_mode text not null default 'dark' check(theme_mode in ('light','dark')), add column if not exists palette_key text not null default 'fio-black', add column if not exists custom_accent text, add column if not exists cover_asset_path text, add column if not exists logo_asset_path text, add column if not exists background_asset_path text;
create table if not exists public.onboarding_progress (barbershop_id uuid primary key references public.barbershops(id) on delete cascade, owner_id uuid not null references auth.users(id), current_step integer not null default 1 check(current_step between 1 and 5), completed_steps jsonb not null default '[]'::jsonb check(jsonb_typeof(completed_steps)='array'), draft jsonb not null default '{}'::jsonb check(jsonb_typeof(draft)='object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists onboarding_owner on public.onboarding_progress(owner_id);
alter table public.onboarding_progress enable row level security;
revoke all on public.onboarding_progress from public,anon,authenticated;
grant select,insert,update on public.onboarding_progress to authenticated;
create policy onboarding_owner_read on public.onboarding_progress for select to authenticated using(owner_id=(select auth.uid()) and public.member_role(barbershop_id)='OWNER');
create policy onboarding_owner_insert on public.onboarding_progress for insert to authenticated with check(owner_id=(select auth.uid()) and public.member_role(barbershop_id)='OWNER');
create policy onboarding_owner_update on public.onboarding_progress for update to authenticated using(owner_id=(select auth.uid()) and public.member_role(barbershop_id)='OWNER') with check(owner_id=(select auth.uid()) and public.member_role(barbershop_id)='OWNER');
create table if not exists public.shop_amenities (barbershop_id uuid not null references public.barbershops(id) on delete cascade, amenity_key text not null check(amenity_key ~ '^[a-z][a-z0-9-]{1,40}$'), enabled boolean not null default true, created_at timestamptz not null default now(), primary key(barbershop_id,amenity_key));
alter table public.shop_amenities enable row level security;
revoke all on public.shop_amenities from public,anon,authenticated;
grant select,insert,update,delete on public.shop_amenities to authenticated;
create policy amenities_owner_read on public.shop_amenities for select to authenticated using(public.member_role(barbershop_id) is not null);
create policy amenities_owner_write on public.shop_amenities for all to authenticated using(public.member_role(barbershop_id)='OWNER') with check(public.member_role(barbershop_id)='OWNER');
create table if not exists public.shop_palettes (palette_key text primary key check(palette_key ~ '^[a-z][a-z0-9-]{1,40}$'), label text not null, light_background text not null check(light_background ~ '^#[0-9A-Fa-f]{6}$'), light_surface text not null check(light_surface ~ '^#[0-9A-Fa-f]{6}$'), light_surface_secondary text not null check(light_surface_secondary ~ '^#[0-9A-Fa-f]{6}$'), light_text text not null check(light_text ~ '^#[0-9A-Fa-f]{6}$'), light_text_muted text not null check(light_text_muted ~ '^#[0-9A-Fa-f]{6}$'), light_accent text not null check(light_accent ~ '^#[0-9A-Fa-f]{6}$'), dark_background text not null check(dark_background ~ '^#[0-9A-Fa-f]{6}$'), dark_surface text not null check(dark_surface ~ '^#[0-9A-Fa-f]{6}$'), dark_surface_secondary text not null check(dark_surface_secondary ~ '^#[0-9A-Fa-f]{6}$'), dark_text text not null check(dark_text ~ '^#[0-9A-Fa-f]{6}$'), dark_text_muted text not null check(dark_text_muted ~ '^#[0-9A-Fa-f]{6}$'), dark_accent text not null check(dark_accent ~ '^#[0-9A-Fa-f]{6}$'), created_at timestamptz not null default now());
insert into public.shop_palettes(palette_key,label,light_background,light_surface,light_surface_secondary,light_text,light_text_muted,light_accent,dark_background,dark_surface,dark_surface_secondary,dark_text,dark_text_muted,dark_accent) values ('fio-black','FIO Black','#f5f5f2','#ffffff','#ecece8','#111111','#626262','#111111','#080808','#111111','#1b1b1b','#f5f5f2','#a6a6a0','#f5f5f2'),('gold','FIO Gold','#fbf8f0','#ffffff','#f1eadb','#201b12','#786f60','#9c6b22','#100e0a','#1b1710','#282014','#fbf8f0','#b9aa8e','#d5a654'),('ivory','FIO Ivory','#f5f0e7','#fffaf1','#ebe2d5','#24201a','#776f63','#6d5b43','#171411','#211e19','#2e2922','#faf3e7','#b8aa98','#d7bd91'),('ocean','FIO Ocean','#eef5f5','#ffffff','#e0eeee','#102526','#607778','#176b70','#081516','#102324','#193538','#edf8f7','#9bbabb','#52c2c3'),('forest','FIO Forest','#f0f5ef','#ffffff','#e3eee1','#142016','#607263','#2d6840','#0a120c','#121d14','#1d2c20','#eff8ef','#a5b7a5','#72c487'),('burgundy','FIO Burgundy','#f7f0f1','#ffffff','#eadde0','#281518','#80666b','#873746','#170b0e','#241317','#352026','#f9eef0','#b99da3','#d06b7d') on conflict(palette_key) do nothing;
alter table public.shop_palettes enable row level security;
revoke all on public.shop_palettes from public,anon,authenticated;
grant select on public.shop_palettes to authenticated,anon;
create policy palettes_public_read on public.shop_palettes for select to authenticated,anon using(true);
create or replace function public.save_onboarding_progress(p_shop uuid,p_step integer,p_completed jsonb,p_draft jsonb) returns public.onboarding_progress language plpgsql security definer set search_path='' as $$ declare row public.onboarding_progress; begin if public.member_role(p_shop) is distinct from 'OWNER' then raise exception 'FORBIDDEN'; end if; if p_step not between 1 and 5 or jsonb_typeof(p_completed)<>'array' or jsonb_typeof(p_draft)<>'object' then raise exception 'INVALID_DATA'; end if; insert into public.onboarding_progress(barbershop_id,owner_id,current_step,completed_steps,draft) values(p_shop,auth.uid(),p_step,p_completed,p_draft) on conflict(barbershop_id) do update set current_step=excluded.current_step,completed_steps=excluded.completed_steps,draft=excluded.draft,updated_at=now() returning * into row; update public.barbershops set onboarding_step=p_step where id=p_shop; return row; end $$;
create or replace function public.activate_owner_onboarding(p_shop uuid) returns void language plpgsql security definer set search_path='' as $$ declare p public.onboarding_progress; shop public.barbershops; begin if public.member_role(p_shop) is distinct from 'OWNER' then raise exception 'FORBIDDEN'; end if; select * into shop from public.barbershops where id=p_shop for update; select * into p from public.onboarding_progress where barbershop_id=p_shop; if shop.name is null or coalesce(shop.whatsapp,'')='' or not exists(select 1 from public.services where barbershop_id=p_shop and active) or not exists(select 1 from public.business_hours where barbershop_id=p_shop) then raise exception 'ONBOARDING_INCOMPLETE'; end if; update public.barbershops set onboarding_completed=true,onboarding_step=5 where id=p_shop; insert into public.audit_events(barbershop_id,actor_id,action,target_id,description) values(p_shop,auth.uid(),'onboarding.activated',p_shop,'Barbearia ativada pelo responsável'); end $$;
create or replace function public.save_owner_setup(p_shop uuid,p_setup jsonb) returns void language plpgsql security definer set search_path='' as $$ declare role_name text; p text; amenities jsonb; begin role_name:=public.member_role(p_shop); if role_name is distinct from 'OWNER' then raise exception 'FORBIDDEN'; end if; if jsonb_typeof(p_setup)<>'object' then raise exception 'INVALID_DATA'; end if; if p_setup ? 'name' and length(trim(coalesce(p_setup->>'name','')))<2 then raise exception 'INVALID_DATA'; end if; if p_setup ? 'slug' and coalesce(p_setup->>'slug','') !~ '^[a-z0-9-]{3,60}$' then raise exception 'INVALID_SLUG'; end if; if p_setup ? 'themeMode' and p_setup->>'themeMode' not in ('light','dark') then raise exception 'INVALID_DATA'; end if; if p_setup ? 'paletteKey' and not exists(select 1 from public.shop_palettes where palette_key=p_setup->>'paletteKey') and p_setup->>'paletteKey'<>'custom' then raise exception 'INVALID_DATA'; end if; if p_setup ? 'customAccent' and p_setup->>'customAccent' is not null and p_setup->>'customAccent' !~ '^#[0-9A-Fa-f]{6}$' then raise exception 'INVALID_ACCENT_COLOR'; end if; if p_setup ? 'slug' and exists(select 1 from public.barbershops where slug=p_setup->>'slug' and id<>p_shop) then raise exception 'SLUG_TAKEN'; end if; update public.barbershops set name=case when p_setup ? 'name' then trim(p_setup->>'name') else name end,slug=case when p_setup ? 'slug' then lower(p_setup->>'slug') else slug end,whatsapp=case when p_setup ? 'whatsapp' then nullif(trim(p_setup->>'whatsapp'),'') else whatsapp end,instagram=case when p_setup ? 'instagram' then nullif(trim(p_setup->>'instagram'),'') else instagram end,address=case when p_setup ? 'address' then nullif(trim(p_setup->>'address'),'') else address end,theme_mode=case when p_setup ? 'themeMode' then p_setup->>'themeMode' else theme_mode end,palette_key=case when p_setup ? 'paletteKey' then p_setup->>'paletteKey' else palette_key end,custom_accent=case when p_setup ? 'customAccent' then nullif(lower(trim(p_setup->>'customAccent')),'') else custom_accent end,public_title=case when p_setup ? 'name' then trim(p_setup->>'name') else public_title end,logo_asset_path=case when p_setup ? 'logoAssetPath' then nullif(trim(p_setup->>'logoAssetPath'),'') else logo_asset_path end,cover_asset_path=case when p_setup ? 'coverAssetPath' then nullif(trim(p_setup->>'coverAssetPath'),'') else cover_asset_path end,background_asset_path=case when p_setup ? 'backgroundAssetPath' then nullif(trim(p_setup->>'backgroundAssetPath'),'') else background_asset_path end where id=p_shop; amenities:=coalesce(p_setup->'amenities','[]'::jsonb); if jsonb_typeof(amenities)<>'array' then raise exception 'INVALID_DATA'; end if; if p_setup ? 'amenities' then delete from public.shop_amenities where barbershop_id=p_shop; insert into public.shop_amenities(barbershop_id,amenity_key) select p_shop,value from jsonb_array_elements_text(amenities) value where value ~ '^[a-z][a-z0-9-]{1,40}$' on conflict do nothing; end if; end $$;
create or replace function public.touch_onboarding_progress() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at:=now(); return new; end $$;
drop trigger if exists onboarding_progress_updated on public.onboarding_progress;
create trigger onboarding_progress_updated before update on public.onboarding_progress for each row execute function public.touch_onboarding_progress();
revoke all on function public.save_onboarding_progress(uuid,integer,jsonb,jsonb),public.activate_owner_onboarding(uuid),public.save_owner_setup(uuid,jsonb),public.touch_onboarding_progress() from public,anon,authenticated;
grant execute on function public.save_onboarding_progress(uuid,integer,jsonb,jsonb),public.activate_owner_onboarding(uuid),public.save_owner_setup(uuid,jsonb) to authenticated;
do $$ begin if to_regclass('storage.buckets') is not null and to_regclass('storage.objects') is not null then insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('branding-assets','branding-assets',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types; execute 'drop policy if exists branding_assets_read on storage.objects'; execute 'create policy branding_assets_read on storage.objects for select to anon,authenticated using(bucket_id=''branding-assets'')'; execute 'drop policy if exists branding_assets_insert on storage.objects'; execute 'create policy branding_assets_insert on storage.objects for insert to authenticated with check(bucket_id=''branding-assets'' and (storage.foldername(name))[1] is not null and (storage.foldername(name))[2]=auth.uid()::text and public.member_role(((storage.foldername(name))[1])::uuid)=''OWNER'' and lower(storage.extension(name)) in (''jpg'',''jpeg'',''png'',''webp''))'; execute 'drop policy if exists branding_assets_update on storage.objects'; execute 'create policy branding_assets_update on storage.objects for update to authenticated using(bucket_id=''branding-assets'' and (storage.foldername(name))[2]=auth.uid()::text and public.member_role(((storage.foldername(name))[1])::uuid)=''OWNER'') with check(bucket_id=''branding-assets'' and (storage.foldername(name))[2]=auth.uid()::text and public.member_role(((storage.foldername(name))[1])::uuid)=''OWNER'')'; execute 'drop policy if exists branding_assets_delete on storage.objects'; execute 'create policy branding_assets_delete on storage.objects for delete to authenticated using(bucket_id=''branding-assets'' and (storage.foldername(name))[2]=auth.uid()::text and public.member_role(((storage.foldername(name))[1])::uuid)=''OWNER'')'; end if; end $$;;
